package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class Phase6c2PermissionGuardTest{@Test void distinguishesOfficeAndIndividualActionsAndScopes(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);PerformanceCommitmentPermissionGuard guard=new PerformanceCommitmentPermissionGuard(client);when(client.resolve(PerformanceCommitmentPermissionGuard.INDIVIDUAL,"t")).thenReturn(new EffectiveFeaturePermission(PerformanceCommitmentPermissionGuard.INDIVIDUAL,false,true,true,true,false,false,false,false,false,false,false,PermissionDataScope.OWN_RECORDS));assertThat(guard.require("IPCR",PrimeHrAction.ADD,"t")).isEqualTo(PermissionDataScope.OWN_RECORDS);assertThatThrownBy(()->guard.require("IPCR",PrimeHrAction.PUBLISH,"t")).isInstanceOf(AccessDeniedException.class);when(client.resolve(PerformanceCommitmentPermissionGuard.OFFICE,"t")).thenReturn(new EffectiveFeaturePermission(PerformanceCommitmentPermissionGuard.OFFICE,false,true,true,true,false,false,false,false,false,false,false,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require("OPCR",PrimeHrAction.ACCESS,"t")).isInstanceOf(AccessDeniedException.class);}}
